  "MoveCoordsInDirection": {
    returnType: "static void",
    params: "u32 dir, s16 *x, s16 *y, s16 deltaX, s16 deltaY",
    lineCount: 11,
    bodyC: "u8 direction = dir;\n    s16 dx2 = (u16)deltaX;\n    s16 dy2 = (u16)deltaY;\n    if (sDirectionToVectors[direction].x > 0)\n        *x += dx2;\n    if (sDirectionToVectors[direction].x < 0)\n        *x -= dx2;\n    if (sDirectionToVectors[direction].y > 0)\n        *y += dy2;\n    if (sDirectionToVectors[direction].y < 0)\n        *y -= dy2;",
  },
  "MoveNextDirectionInSequence": {
    returnType: "bool8",
    params: "struct ObjectEvent *objectEvent, struct Sprite *sprite, u8 *route",
    callsTo: ["GetCollisionInDirection","GetWalkInPlaceNormalMovementAction","GetWalkNormalMovementAction","ObjectEventSetSingleMovement","SetObjectEventDirection"],
    lineCount: 20,
    bodyC: "u8 collision;\n    u8 movementActionId;\n\n    if (objectEvent->directionSequenceIndex == 3 && objectEvent->initialCoords.x == objectEvent->currentCoords.x && objectEvent->initialCoords.y == objectEvent->currentCoords.y)\n        objectEvent->directionSequenceIndex = 0;\n\n    SetObjectEventDirection(objectEvent, route[objectEvent->directionSequenceIndex]);\n    movementActionId = GetWalkNormalMovementAction(objectEvent->movementDirection);\n    collision = GetCollisionInDirection(objectEvent, objectEvent->movementDirection);\n    if (collision == COLLISION_OUTSIDE_RANGE)\n    {\n        objectEvent->directionSequenceIndex++;\n        SetObjectEventDirection(objectEvent, route[objectEvent->directionSequenceIndex]);\n        movementActionId = GetWalkNormalMovementAction(objectEvent->movementDirection);\n        collision = GetCollisionInDirection(objectEvent, objectEvent->movementDirection);\n    }\n\n    if (collision)\n        movementActionId = GetWalkInPlaceNormalMovementAction(objectEvent->facingDirection);\n\n    ObjectEventSetSingleMovement(objectEvent, sprite, movementActionId);\n    objectEvent->singleMovementActive = TRUE;\n    sprite->sTypeFuncId = 2;\n    return TRUE;",
  },
  "MoveObjectEventToMapCoords": {
    returnType: "void",
    params: "struct ObjectEvent *objectEvent, s16 x, s16 y",
    callsTo: ["CameraObjectReset","GetObjectEventGraphicsInfo","ResetObjectEventFldEffData","SetObjectEventCoords","SetSpritePosToMapCoords"],
    lineCount: 13,
    bodyC: "struct Sprite *sprite;\n    const struct ObjectEventGraphicsInfo *graphicsInfo;\n\n    sprite = &gSprites[objectEvent->spriteId];\n    graphicsInfo = GetObjectEventGraphicsInfo(objectEvent->graphicsId);\n    SetObjectEventCoords(objectEvent, x, y);\n    SetSpritePosToMapCoords(objectEvent->currentCoords.x, objectEvent->currentCoords.y, &sprite->x, &sprite->y);\n    sprite->centerToCornerVecX = -(graphicsInfo->width >> 1);\n    sprite->centerToCornerVecY = -(graphicsInfo->height >> 1);\n    sprite->x += 8;\n    sprite->y += 16 + sprite->centerToCornerVecY;\n    ResetObjectEventFldEffData(objectEvent);\n    if (objectEvent->trackedByCamera)\n        CameraObjectReset();",
  },
  "MoveUnionRoomObjectDown": {
    returnType: "static void",
    params: "struct Sprite *sprite",
    lineCount: 13,
    bodyC: "switch(sprite->sAnimState)\n    {\n    case 0:\n        sprite->y2 = -DISPLAY_HEIGHT;\n        sprite->sAnimState++;\n    case 1:\n        sprite->y2 += 8;\n        if(sprite->y2 == 0)\n        {\n            sprite->sAnimNum = 0;\n            sprite->sAnimState = 0;\n        }\n    }",
  },
  "MoveUnionRoomObjectUp": {
    returnType: "static void",
    params: "struct Sprite *sprite",
    lineCount: 15,
    bodyC: "switch(sprite->sAnimState)\n    {\n    case 0:\n        sprite->y2 = 0;\n        sprite->sAnimState++;\n    case 1:\n        sprite->y2 -= 8;\n        if (sprite->y2 == -DISPLAY_HEIGHT)\n        {\n            sprite->y2 = 0;\n            sprite->sInvisible = TRUE;\n            sprite->sAnimNum = 0;\n            sprite->sAnimState = 0;\n        }\n    }",
  },
