  "ObjectEventGetNearbyReflectionType": {
    returnType: "static u8",
    params: "struct ObjectEvent *objEvent",
    callsTo: ["GetObjectEventGraphicsInfo","RETURN_REFLECTION_TYPE_AT"],
    lineCount: 19,
    bodyC: "const struct ObjectEventGraphicsInfo *info = GetObjectEventGraphicsInfo(objEvent->graphicsId);\n\n     \n    s16 width = (info->width + 8) >> 4;\n    s16 height = (info->height + 8) >> 4;\n    s16 i, j;\n    u8 result, b;  \n    s16 one = 1;\n\n    for (i = 0; i < height; i++)\n    {\n        RETURN_REFLECTION_TYPE_AT(objEvent->currentCoords.x, objEvent->currentCoords.y + one + i)\n        RETURN_REFLECTION_TYPE_AT(objEvent->previousCoords.x, objEvent->previousCoords.y + one + i)\n        for (j = 1; j < width; j++)\n        {\n            RETURN_REFLECTION_TYPE_AT(objEvent->currentCoords.x + j, objEvent->currentCoords.y + one + i)\n            RETURN_REFLECTION_TYPE_AT(objEvent->currentCoords.x - j, objEvent->currentCoords.y + one + i)\n            RETURN_REFLECTION_TYPE_AT(objEvent->previousCoords.x + j, objEvent->previousCoords.y + one + i)\n            RETURN_REFLECTION_TYPE_AT(objEvent->previousCoords.x - j, objEvent->previousCoords.y + one + i)\n        }\n    }\n\n    return REFL_TYPE_NONE;",
  },
